sqlite3 -json /Users/Residentialist/.openclaw/workspace/residentialist/residentialist.db "SELECT p.product_name, p.quality_score, p.durability_score, p.performance_score, p.overall_score, s.quality as s_quality, s.durability as s_durability, s.performance as s_performance, s.overall as s_overall, s.scored_at FROM products p LEFT JOIN scores s ON s.product_id = p.id WHERE p.product_name LIKE '%Marvin Signature%' OR p.product_name LIKE '%Andersen 400%' OR p.product_name LIKE '%Pella Impervia%' ORDER BY s.scored_at DESC"
